import * as SDK from "@pury-fi/plugin-sdk/websocket";
import * as fs from "node:fs";
import * as path from "node:path";
import { fileURLToPath } from "node:url";

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);
const DATA_DIR = path.resolve(__dirname, "../data");
const CROPS_DIR = path.resolve(DATA_DIR, "crops");
const SETTINGS_FILE = path.resolve(DATA_DIR, "settings.json");
const CONFIG_FILE = path.resolve(__dirname, "../config.json");

function getPort(): number {
   if (process.env.PORT) {
      const p = parseInt(process.env.PORT, 10);
      if (!isNaN(p)) return p;
   }
   if (fs.existsSync(CONFIG_FILE)) {
      try {
         const parsed = JSON.parse(fs.readFileSync(CONFIG_FILE, "utf-8"));
         if (typeof parsed.port === "number") return parsed.port;
      } catch (e) {}
   }
   if (fs.existsSync(SETTINGS_FILE)) {
      try {
         const parsed = JSON.parse(fs.readFileSync(SETTINGS_FILE, "utf-8"));
         if (typeof parsed.port === "number") return parsed.port;
      } catch (e) {}
   }
   return 8080;
}

const PORT = getPort();
const TOP_K_CANDIDATES = 50;

interface Crop {
   id: string;
   width: number;
   height: number;
   aspectRatio: number;
   pixels: Uint8Array;
   filePath?: string;
}

interface PluginSettings {
   selectedBodyParts: string[];
   storageMode: "MEMORY" | "DISK";
   maxPoolSize: number;
   maxCropDimension: number;
}

const defaultSettings: PluginSettings = {
   selectedBodyParts: [],
   storageMode: "MEMORY",
   maxPoolSize: 100,
   maxCropDimension: 512,
};

let settings: PluginSettings = { ...defaultSettings };
let cropPool: Crop[] = [];

