function ensureDirectories() {
   if (!fs.existsSync(DATA_DIR)) {
      fs.mkdirSync(DATA_DIR, { recursive: true });
   }
   if (!fs.existsSync(CROPS_DIR)) {
      fs.mkdirSync(CROPS_DIR, { recursive: true });
   }
}

function loadSettings() {
   ensureDirectories();
   if (fs.existsSync(SETTINGS_FILE)) {
      try {
         const raw = fs.readFileSync(SETTINGS_FILE, "utf-8");
         const parsed = JSON.parse(raw);
         const loadedParts =
            Array.isArray(parsed.selectedBodyParts) && parsed.selectedBodyParts.length > 0
               ? parsed.selectedBodyParts
               : defaultSettings.selectedBodyParts;

         settings = {
            selectedBodyParts: loadedParts,
            storageMode: parsed.storageMode === "DISK" ? "DISK" : "MEMORY",
            maxPoolSize:
               typeof parsed.maxPoolSize === "number"
                  ? Math.max(10, Math.min(10000, parsed.maxPoolSize))
                  : defaultSettings.maxPoolSize,
            maxCropDimension:
               typeof parsed.maxCropDimension === "number"
                  ? Math.max(128, Math.min(2048, parsed.maxCropDimension))
                  : defaultSettings.maxCropDimension,
         };
         console.log("[AutoCrop Plugin] Persistent settings loaded:", settings);
      } catch (err) {
         console.error("[AutoCrop Plugin] Error reading settings.json:", err);
      }
   }
}

function saveSettings() {
   ensureDirectories();
   try {
      fs.writeFileSync(SETTINGS_FILE, JSON.stringify(settings, null, 2), "utf-8");
      console.log("[AutoCrop Plugin] Persistent settings saved to disk:", settings);
   } catch (err) {
      console.error("[AutoCrop Plugin] Error saving settings.json:", err);
   }
}

function getLabelFolderName(label?: number | string): string {
   if (label === undefined || label === null) return "UNCATEGORIZED";
   if (typeof label === "number") {
      return LABEL_NAMES[label] || `LABEL_${label}`;
   }
   return String(label).toUpperCase().replace(/[^A-Z0-9_-]/g, "_");
}

function saveCropToDisk(crop: Crop, label?: number | string): string | undefined {
   ensureDirectories();
   try {
      const folderName = getLabelFolderName(label);
      const targetDir = path.join(CROPS_DIR, folderName);
      if (!fs.existsSync(targetDir)) {
         fs.mkdirSync(targetDir, { recursive: true });
      }

      const fileName = `crop_${Date.now()}_${Math.random().toString(36).substring(2, 8)}_${crop.width}x${crop.height}.crop`;
      const filePath = path.join(targetDir, fileName);

      const header = Buffer.alloc(8);
      header.writeUInt32LE(crop.width, 0);
      header.writeUInt32LE(crop.height, 4);

      const fileBuffer = Buffer.concat([header, Buffer.from(crop.pixels)]);
      fs.writeFileSync(filePath, fileBuffer);
      return filePath;
   } catch (err) {
      console.error("[AutoCrop Plugin] Error saving crop file to disk:", err);
      return undefined;
   }
}

function getAllCropFiles(dir: string): string[] {
   let results: string[] = [];
   if (!fs.existsSync(dir)) return results;
   const entries = fs.readdirSync(dir, { withFileTypes: true });
   for (const entry of entries) {
      const fullPath = path.join(dir, entry.name);
      if (entry.isDirectory()) {
         results = results.concat(getAllCropFiles(fullPath));
      } else if (entry.isFile() && entry.name.endsWith(".crop")) {
         results.push(fullPath);
      }
   }
   return results;
}

function loadCropsFromDisk() {
   ensureDirectories();
   if (settings.storageMode !== "DISK") return;

   cropPool = [];
   try {
      const cropFiles = getAllCropFiles(CROPS_DIR);
      console.log(`[AutoCrop Plugin] Loading persistent crops from ${CROPS_DIR} (${cropFiles.length} files found)...`);

      for (const filePath of cropFiles) {
         if (cropPool.length >= settings.maxPoolSize) break;
         const data = fs.readFileSync(filePath);
         if (data.length < 8) continue;

         const width = data.readUInt32LE(0);
         const height = data.readUInt32LE(4);
         const expectedPixelLen = width * height * 4;

         if (data.length >= 8 + expectedPixelLen) {
            const rawPixels = new Uint8Array(data.buffer, data.byteOffset + 8, expectedPixelLen);
            cropPool.push({
               id: path.basename(filePath),
               width,
               height,
               aspectRatio: width / height,
               pixels: new Uint8Array(rawPixels),
               filePath,
            });
         }
      }
      console.log(`[AutoCrop Plugin] Loaded ${cropPool.length} persistent crops into pool.`);
   } catch (err) {
      console.error("[AutoCrop Plugin] Error loading crops from disk:", err);
   }
}

function clearActiveCrops() {
   if (settings.storageMode === "DISK") {
      ensureDirectories();
      try {
         const cropFiles = getAllCropFiles(CROPS_DIR);
         for (const filePath of cropFiles) {
            try {
               fs.unlinkSync(filePath);
            } catch (e) {}
         }
         // Clean up empty directories
         const subDirs = fs.readdirSync(CROPS_DIR, { withFileTypes: true }).filter((d) => d.isDirectory());
         for (const sub of subDirs) {
            try {
               fs.rmSync(path.join(CROPS_DIR, sub.name), { recursive: true, force: true });
            } catch (e) {}
         }
         console.log(`[AutoCrop Plugin] Cleared ${cropFiles.length} persistent crop files from disk.`);
      } catch (err) {
         console.error("[AutoCrop Plugin] Error clearing disk crops:", err);
      }
   }
   cropPool = [];
   console.log(`[AutoCrop Plugin] Cleared active crop pool.`);
}

function matchesSelectedBodyParts(label: number, targets: string[] | string): boolean {
   const targetArray = Array.isArray(targets) ? targets : [targets];
   if (targetArray.length === 0) {
      return true; // Match all if none explicitly filtered
   }
   const labelName = LABEL_NAMES[label]?.toUpperCase() ?? "";
   return targetArray.some((target) => {
      const normalized = target.toUpperCase().trim();
      return (
         labelName === normalized ||
         label.toString() === normalized
      );
   });
}

function cropImageRegion(
   image: Uint8Array,
   imgW: number,
   imgH: number,
   startX: number,
   startY: number,
   boxW: number,
   boxH: number,
   maxDim: number
): Crop | null {
   if (boxW <= 0 || boxH <= 0) return null;

   const rawPixels = new Uint8Array(boxW * boxH * 4);
   for (let py = 0; py < boxH; py++) {
      const srcY = startY + py;
      if (srcY < 0 || srcY >= imgH) continue;
      for (let px = 0; px < boxW; px++) {
         const srcX = startX + px;
         if (srcX < 0 || srcX >= imgW) continue;
         const srcIdx = (srcY * imgW + srcX) * 4;
         const dstIdx = (py * boxW + px) * 4;
         rawPixels[dstIdx + 0] = image[srcIdx + 0];
         rawPixels[dstIdx + 1] = image[srcIdx + 1];
         rawPixels[dstIdx + 2] = image[srcIdx + 2];
         rawPixels[dstIdx + 3] = image[srcIdx + 3];
      }
   }

   // Downscale crop if it exceeds maxCropDimension
   if (boxW <= maxDim && boxH <= maxDim) {
      return {
         id: `crop_${Date.now()}_${Math.random().toString(36).substring(2, 6)}`,
         width: boxW,
         height: boxH,
         aspectRatio: boxW / boxH,
         pixels: rawPixels,
      };
   }

   const scale = Math.min(maxDim / boxW, maxDim / boxH);
   const dstW = Math.max(1, Math.floor(boxW * scale));
   const dstH = Math.max(1, Math.floor(boxH * scale));
   const dstPixels = new Uint8Array(dstW * dstH * 4);

   for (let py = 0; py < dstH; py++) {
      const srcY = Math.min(boxH - 1, Math.floor(py / scale));
      for (let px = 0; px < dstW; px++) {
         const srcX = Math.min(boxW - 1, Math.floor(px / scale));
         const srcIdx = (srcY * boxW + srcX) * 4;
         const dstIdx = (py * dstW + px) * 4;

         dstPixels[dstIdx + 0] = rawPixels[srcIdx + 0];
         dstPixels[dstIdx + 1] = rawPixels[srcIdx + 1];
         dstPixels[dstIdx + 2] = rawPixels[srcIdx + 2];
         dstPixels[dstIdx + 3] = rawPixels[srcIdx + 3];
      }
   }

   return {
      id: `crop_${Date.now()}_${Math.random().toString(36).substring(2, 6)}`,
      width: dstW,
      height: dstH,
      aspectRatio: dstW / dstH,
      pixels: dstPixels,
   };
}

function findBestCropCandidate(targetW: number, targetH: number): Crop | null {
   if (cropPool.length === 0 || targetW <= 0 || targetH <= 0) return null;
   const targetAspect = targetW / targetH;

   // Score crops by symmetric log aspect ratio distance
   const scored = cropPool.map((crop) => {
      const diff = Math.abs(Math.log(crop.aspectRatio / targetAspect));
      return { crop, diff };
   });

   // Sort ascending by aspect ratio difference
   scored.sort((a, b) => a.diff - b.diff);

   // Select top K best aspect-matched candidates
   const count = Math.min(TOP_K_CANDIDATES, scored.length);
   const topCandidates = scored.slice(0, count);

   // Pick one randomly from top candidates
   const selected = topCandidates[Math.floor(Math.random() * topCandidates.length)];
   return selected.crop;
}

function invertBoxRegion(
   targetImage: Uint8Array,
   imgW: number,
   imgH: number,
   startX: number,
   startY: number,
   boxW: number,
   boxH: number
) {
   for (let py = 0; py < boxH; py++) {
      const dstY = startY + py;
      if (dstY < 0 || dstY >= imgH) continue;
      for (let px = 0; px < boxW; px++) {
         const dstX = startX + px;
         if (dstX < 0 || dstX >= imgW) continue;
         const idx = (dstY * imgW + dstX) * 4;
         targetImage[idx + 0] = 255 - targetImage[idx + 0];
         targetImage[idx + 1] = 255 - targetImage[idx + 1];
         targetImage[idx + 2] = 255 - targetImage[idx + 2];
      }
   }
}

function blitCropAspectPreserved(
   targetImage: Uint8Array,
   imgW: number,
   imgH: number,
   targetX: number,
   targetY: number,
   targetW: number,
   targetH: number,
   crop: Crop
) {
   const srcW = crop.width;
   const srcH = crop.height;
   if (srcW <= 0 || srcH <= 0 || targetW <= 0 || targetH <= 0) return;

   // Scale crop to fit target box preserving aspect ratio (0% clipped)
   const scale = Math.min(targetW / srcW, targetH / srcH);
   const fitW = Math.max(1, Math.floor(srcW * scale));
   const fitH = Math.max(1, Math.floor(srcH * scale));

   const marginX = Math.floor((targetW - fitW) / 2);
   const marginY = Math.floor((targetH - fitH) / 2);

   for (let py = 0; py < fitH; py++) {
      const dstY = targetY + marginY + py;
      if (dstY < 0 || dstY >= imgH) continue;
      const srcY = Math.min(srcH - 1, Math.floor(py / scale));

      for (let px = 0; px < fitW; px++) {
         const dstX = targetX + marginX + px;
         if (dstX < 0 || dstX >= imgW) continue;
         const srcX = Math.min(srcW - 1, Math.floor(px / scale));

         const srcIdx = (srcY * srcW + srcX) * 4;
         const dstIdx = (dstY * imgW + dstX) * 4;

         targetImage[dstIdx + 0] = crop.pixels[srcIdx + 0];
         targetImage[dstIdx + 1] = crop.pixels[srcIdx + 1];
         targetImage[dstIdx + 2] = crop.pixels[srcIdx + 2];
         targetImage[dstIdx + 3] = crop.pixels[srcIdx + 3];
      }
   }
}

// Load initial settings and crops on startup
loadSettings();
if (settings.storageMode === "DISK") {
   loadCropsFromDisk();
}

console.log(`[AutoCrop Plugin] Starting WebSocket server on port ${PORT}... (ws://localhost:${PORT})`);

const server = new SDK.WebSocketServer(PORT);

server.on("connection", (connection) => {
   console.log("[AutoCrop Plugin] PuryFi extension connected!");

   connection.once("open", async () => {
      // 1. Handle Handshake
      await new Promise<void>((resolve) => {
         connection.once("message", "ready", (payload) => {
            const res = connection.handleReadyMessage(payload);
            if (res.type === "ok") {
               resolve();
            }
            return res;
         });
      });

      console.log("[AutoCrop Plugin] Handshake successful.");

      const manifest: SDK.PluginManifest = {
         name: "AutoCrop Plugin",
         version: "2.7.0",
         description: "Censor plugin with persistent storage, crop harvest filtering & extension censor blitting",
         author: null,
         website: null,
         censorModes: [
            {
               id: "autocrop",
               name: "AutoCrop",
               tooltip: "AutoCrop",
               icon: "data:image/png;base64,",
},
         ],
      };

      const buildConfiguration = (): SDK.PluginConfiguration => {
         return {
            storageStatus: {
               name: `Crops Stored: ${cropPool.length}`,
               type: "string",
               value: `${cropPool.length}`,
            },
            targetBodyParts: {
               name: "Cropped Body Parts",
               type: "multiselect",
               value: settings.selectedBodyParts,
               options: ALL_BODY_PART_OPTIONS,
            },
            storageMode: {
               name: "Crop Storage",
               type: "select",
               value: settings.storageMode,
               options: [
                  { label: "RAM (In-Memory Only)", value: "MEMORY" },
                  { label: "Disk Storage (Persistent Folder)", value: "DISK" },
               ],
            },
            maxPoolSize: {
               name: "Maximum Crop Pool Capacity",
               type: "number",
               value: settings.maxPoolSize,
            },
            maxCropDimension: {
               name: "Maximum Crop Pixel Dimension (px)",
               type: "number",
               value: settings.maxCropDimension,
            },
            clearCropsAction: {
               name: "Clear Active Crop Storage Pool",
               type: "action",
               value: false,
            },
         };
      };

      await connection.sendMessage("setPluginManifest", { manifest });
      await connection.sendMessage("setPluginConfiguration", { configuration: buildConfiguration() });

      // Handle Configuration Changes from PuryFi Extension UI
      connection.on("message", "configurationChange", async (payload) => {
         let changed = false;

         if (payload.configuration?.targetBodyParts) {
            const val = payload.configuration.targetBodyParts.value;
            if (Array.isArray(val)) {
               settings.selectedBodyParts = val.map(String);
               changed = true;
            }
         }

         if (payload.configuration?.storageMode) {
            const oldMode = settings.storageMode;
            const newMode = String(payload.configuration.storageMode.value) === "DISK" ? "DISK" : "MEMORY";
            if (oldMode !== newMode) {
               settings.storageMode = newMode;
               changed = true;
               if (newMode === "DISK") {
                  loadCropsFromDisk();
               }
            }
         }

         if (payload.configuration?.maxPoolSize) {
            const val = Number(payload.configuration.maxPoolSize.value);
            if (!isNaN(val) && val > 0) {
               settings.maxPoolSize = Math.max(10, Math.min(10000, Math.floor(val)));
               changed = true;
               while (cropPool.length > settings.maxPoolSize) {
                  const oldest = cropPool.shift();
                  if (oldest?.filePath && fs.existsSync(oldest.filePath)) {
                     try {
                        fs.unlinkSync(oldest.filePath);
                     } catch (e) {}
                  }
               }
            }
         }

         if (payload.configuration?.maxCropDimension) {
            const val = Number(payload.configuration.maxCropDimension.value);
            if (!isNaN(val) && val > 0) {
               settings.maxCropDimension = Math.max(128, Math.min(2048, Math.floor(val)));
               changed = true;
            }
         }

         if (payload.configuration?.clearCropsAction?.value === true) {
            clearActiveCrops();
            changed = true;
         }

         if (changed) {
            saveSettings();
            await connection.sendMessage("setPluginConfiguration", { configuration: buildConfiguration() });
         }
      });

      // 3. Request Intents and Subscribe to Pre-Censor Hook
      const requiredIntents: SDK.PluginIntent[] = [
         "requestMediaCensorHooks",
         "readMediaProcesses",
         "requestMediaProcesses",
      ];

      let isSubscribed = false;
      const subscribeAllHooks = async () => {
         if (isSubscribed) return;
         const subRes = await connection.sendMessage("subscribeToMediaCensorHooks", {
            stage: "before",
            onlyIfObjectsDetected: true,
            timeout: 5000,
         });
         console.log("[AutoCrop Plugin] Subscribed to before-censor hook (timeout: 5000ms):", subRes);
         if (subRes.type === "ok") {
            isSubscribed = true;
         }
      };

      connection.on("message", "intentsGrant", async (payload) => {
         const granted = payload.intents || [];
         console.log("[AutoCrop Plugin] Intents granted event received:", granted);
         if (requiredIntents.every((intent) => granted.includes(intent))) {
            await subscribeAllHooks();
         }
      });

      console.log("[AutoCrop Plugin] Checking plugin intents...");
      const getRes = await connection.sendMessage("getPluginIntents", {});
      const grantedIntents = getRes.type === "ok" ? getRes.intents : [];
      console.log("[AutoCrop Plugin] Currently granted intents:", grantedIntents);

      if (requiredIntents.every((intent) => grantedIntents.includes(intent))) {
         await subscribeAllHooks();
      } else {
         console.log("[AutoCrop Plugin] Requesting missing intents from extension...");
         await connection.sendMessage("requestPluginIntents", {
            intents: requiredIntents,
         });
      }

      // 4. Handle Hook Requests
      connection.on("message", "mediaCensorHookRequest", (payload) => {
         const { stage, image, objects, width, height, url, isVideo: rawIsVideo, metadata } = payload as any;
         
         // Detect if this is a video frame
         const isVideo = Boolean(
            rawIsVideo ||
            metadata?.isVideo ||
            (typeof url === "string" && (
               url.includes("video") ||
               url.includes(".mp4") ||
               url.includes(".m3u8") ||
               url.startsWith("blob:")
            ))
         );

         console.log("\n=================== [AutoCrop Hook Request] ===================");
         console.log(`[DEBUG] Stage: "${stage}", Dimensions: ${width}x${height}, isVideo: ${isVideo}, URL: "${url || 'none'}"`);
         console.log(`[DEBUG] Censor Objects passed (count: ${objects?.length ?? 0}):`, objects);
         console.log(`[DEBUG] Metadata passed:`, metadata);
         console.log(`[DEBUG] Current Active Plugin Filters:`, settings.selectedBodyParts);

         const harvestObjects = metadata?.rawObjects || objects || [];
         console.log(`[DEBUG] Harvest Candidates total count: ${harvestObjects.length}`);

         if (stage === "before") {
            const modifiedImage = new Uint8Array(image.slice());
            let newCropsHarvested = 0;

            // Step A: HARVEST CROPS into cropPool (filtered by plugin's selectedBodyParts, disabled on video frames)
            if (!isVideo && harvestObjects.length > 0) {
               console.log(`[DEBUG Step A] Checking ${harvestObjects.length} objects against filters...`);
               for (const obj of harvestObjects) {
                  const labelStr = LABEL_NAMES[obj.label] || `LABEL_${obj.label}`;
                  const isMatch = matchesSelectedBodyParts(obj.label, settings.selectedBodyParts);
                  console.log(`   -> Object Label #${obj.label} ("${labelStr}"), Score: ${obj.score}, Rect: [x:${obj.rect?.x}, y:${obj.rect?.y}, w:${obj.rect?.width}, h:${obj.rect?.height}] => MATCH: ${isMatch}`);

                  if (isMatch) {
                     const r = obj.rect;
                     const isFraction = r.x <= 1.0 && r.y <= 1.0 && r.width <= 1.0 && r.height <= 1.0;

                     const pxX = isFraction ? r.x * width : r.x;
                     const pxY = isFraction ? r.y * height : r.y;
                     const pxW = isFraction ? r.width * width : r.width;
                     const pxH = isFraction ? r.height * height : r.height;

                     const startX = Math.max(0, Math.floor(pxX));
                     const startY = Math.max(0, Math.floor(pxY));
                     const boxW = Math.min(width - startX, Math.ceil(pxW));
                     const boxH = Math.min(height - startY, Math.ceil(pxH));

                     console.log(`      [Crop Region] Computed Box: [startX: ${startX}, startY: ${startY}, w: ${boxW}, h: ${boxH}]`);

                     const crop = cropImageRegion(image, width, height, startX, startY, boxW, boxH, settings.maxCropDimension);
                     if (crop && crop.pixels.length > 0) {
                        if (settings.storageMode === "DISK") {
                           crop.filePath = saveCropToDisk(crop, obj.label);
                           console.log(`      [Disk Save] Saved to file: ${crop.filePath}`);
                        }

                        console.log(`      [Harvest SUCCESS] Added crop to pool! Current pool size: ${cropPool.length + 1}`);
                        cropPool.push(crop);
                        newCropsHarvested++;

                        // Trim pool if size exceeds capacity
                        while (cropPool.length > settings.maxPoolSize) {
                           const oldest = cropPool.shift();
                           if (oldest?.filePath && fs.existsSync(oldest.filePath)) {
                              try {
                                 fs.unlinkSync(oldest.filePath);
                              } catch (e) {}
                           }
                        }
                     } else {
                        console.warn(`      [Crop WARNING] cropImageRegion returned null or empty pixels!`);
                     }
                  }
               }

               if (newCropsHarvested > 0) {
                  connection.sendMessage("setPluginConfiguration", { configuration: buildConfiguration() }).catch(() => {});
               }
            } else if (isVideo) {
               console.log(`[DEBUG Step A] Skipping harvest because frame was detected as video.`);
            } else {
               console.log(`[DEBUG Step A] No harvest objects available.`);
            }

            // Step B: CENSOR ALL ACTIVE BOXES passed by PuryFirefox extension!
            const isAutoCropActive = metadata?.censorName === "autocrop";
            console.log(`[DEBUG Step B] Active censorName: "${metadata?.censorName}", isAutoCropActive: ${isAutoCropActive}`);

            if (!isAutoCropActive) {
               console.log(`[DEBUG Step B] AutoCrop mode not active (active: ${metadata?.censorName}). Skipping image replacement, letting PuryFi handle internal censoring.`);
               console.log("===============================================================\n");
               return { type: "pass" };
            }

            let censoredCount = 0;
            const censorObjects = objects || [];
            const censorCfg = metadata?.censorConfig;
            const censorScale = (censorCfg?.presets?.[0]?.config?.scale) ?? 1.0;
            console.log(`[DEBUG Step B] Censoring ${censorObjects.length} active extension boxes with censor scale: ${censorScale}x...`);
            for (const obj of censorObjects) {
               const r = obj.rect;
               const isFraction = r.x <= 1.0 && r.y <= 1.0 && r.width <= 1.0 && r.height <= 1.0;

               const rawX = isFraction ? r.x * width : r.x;
               const rawY = isFraction ? r.y * height : r.y;
               const rawW = isFraction ? r.width * width : r.width;
               const rawH = isFraction ? r.height * height : r.height;

               // Apply censor mode scale factor (expanding from box center)
               const centerX = rawX + rawW / 2;
               const centerY = rawY + rawH / 2;
               const scaledW = rawW * censorScale;
               const scaledH = rawH * censorScale;

               const pxX = centerX - scaledW / 2;
               const pxY = centerY - scaledH / 2;

               const startX = Math.max(0, Math.floor(pxX));
               const startY = Math.max(0, Math.floor(pxY));
               const endX = Math.min(width, Math.ceil(pxX + scaledW));
               const endY = Math.min(height, Math.ceil(pxY + scaledH));
               const boxW = Math.max(1, endX - startX);
               const boxH = Math.max(1, endY - startY);

               // Find best aspect-ratio matched candidate from pool
               const chosenCrop = findBestCropCandidate(boxW, boxH);

               if (chosenCrop) {
                  blitCropAspectPreserved(modifiedImage, width, height, startX, startY, boxW, boxH, chosenCrop);
                  censoredCount++;
               } else {
                  console.log(`[DEBUG Step B] Pool empty, applying color inversion placeholder for box [${startX}, ${startY}, ${boxW}, ${boxH}]`);
                  invertBoxRegion(modifiedImage, width, height, startX, startY, boxW, boxH);
                  censoredCount++;
               }
            }

            if (censoredCount > 0) {
               console.log(`[DEBUG Step B] Censored ${censoredCount} boxes. Returning { type: "ok", skipInternalCensoring: true }`);
               console.log("===============================================================\n");
               return {
                  type: "ok",
                  image: modifiedImage,
                  skipInternalCensoring: true,
               };
            }

            console.log(`[DEBUG Step B] No boxes censored (pool size: ${cropPool.length}). Returning { type: "pass" }`);
            console.log("===============================================================\n");
         }

         return { type: "pass" };
      });
   });
});

server.on("error", (err) => {
   console.error("[AutoCrop Plugin] Server error:", err);
});
